begin;

-- §18.66 (owner ruling - five-field unification): Registration surface narrowed to name/status/engine/knowledge_text/max_severity.
-- Reshapes definition to {knowledge_text,max_severity,version}: retires finding_template and severity_whitelist --
-- finding key becomes a system-derived row attribute (finding_key column), and severity whitelist semantics are replaced
-- by downward closure from max_severity (info..selected). The 48 built-in rows (seeded in 000009) use precomputed
-- Go-Marshal-equivalent hashes (pinned by TestB8MigrationSkillPackageIntegrity); non-builtin and knowledge rows are
-- reshaped in-database with PG sha256 matching canonical Go form.

alter table prompt_tools add column finding_key text;
alter table knowledge_entries add column finding_key text;

update prompt_tools set finding_key='builtin.dml-require-where', definition='{"knowledge_text":"规则：UPDATE或DELETE必须携带WHERE条件。判定依据：组的representative_shape中where=false（statistics.unbounded_mutation=true）且op为update或delete时输出本发现；事实缺失不输出。","max_severity":"high","version":1}'::jsonb, config_hash='e50372219a11d336dbceb42bb5a258c969fb556f5a1c429c0b12c44cbbc89faf' where name='builtin.dml-require-where' and is_builtin;
