update prompt_tools set finding_key='builtin.dml-forbid-subselect', definition='{"knowledge_text":"规则：DML语句禁止内嵌SELECT子查询（旧DMLSelect）。判定依据：statistics.dml_has_subselect=true时输出本发现。","max_severity":"medium","version":1}'::jsonb, config_hash='b4ba491da4686a984f3decab9228a0918a9ce8bd06057a20c057a2e87c0d88d6' where name='builtin.dml-forbid-subselect' and is_builtin;
update prompt_tools set finding_key='builtin.dml-insert-explicit-columns', definition='{"knowledge_text":"规则：INSERT必须显式声明目标列（旧DMLInsertColumns与DMLInsertMustExplicitly语义合并）。判定依据：statistics.insert_has_columns=false时输出本发现。","max_severity":"medium","version":1}'::jsonb, config_hash='83ef9e2e0d02cc989d018b7c43c0984904b8f26696e25ee95c066c1619c8037a' where name='builtin.dml-insert-explicit-columns' and is_builtin;
