update prompt_tools set finding_key='builtin.ddl-multi-alter', definition='{"knowledge_text":"规则：单个工单禁止多条ALTER（旧DDLAllowMultiAlter）。判定依据：上下文中全部alter组的statement_count之和大于1时输出本发现（对每个alter组各输出一次）。","max_severity":"low","version":1}'::jsonb, config_hash='76f9ba6a56b9bc357768c789f1057fffd745e491f519f8692e758e12a19e8571' where name='builtin.ddl-multi-alter' and is_builtin;
update prompt_tools set finding_key='builtin.ddl-multi-ddl', definition='{"knowledge_text":"规则：单个工单仅允许一条DDL（旧DDLMultiToCommit）。判定依据：上下文中全部ddl组（含alter/create/drop等）的statement_count之和大于1时输出本发现。","max_severity":"low","version":1}'::jsonb, config_hash='70fa38468d4112d852c2c8427a3d22ff5dcaf36aa7318a1e5a548e2b33f68f32' where name='builtin.ddl-multi-ddl' and is_builtin;
update prompt_tools set finding_key='builtin.max-affect-rows', definition='{"knowledge_text":"规则：语句预估影响行数不得超过{{max_affect_rows}}。判定依据：调用safe_explain工具取得EstimatedRows事实；EstimatedRows大于{{max_affect_rows}}时输出本发现；无法取得事实时不输出并注明unknown。","max_severity":"high","version":1}'::jsonb, config_hash='eaf7ab48342d981ffa6d7bc90d68cfc066a29c904884bd07f06686dea9a63713' where name='builtin.max-affect-rows' and is_builtin;
update prompt_tools set finding_key='builtin.ddl-max-affect-rows', definition='{"knowledge_text":"规则：DDL作用表行数不得超过{{max_ddl_affect_rows}}。判定依据：调用table_statistics工具取得目标表行数；行数大于{{max_ddl_affect_rows}}时输出本发现；无法取得事实时不输出并注明unknown。","max_severity":"medium","version":1}'::jsonb, config_hash='15984e11127f2473d9de3d9a65a0c0d9e2b5609e3e2404165aa249a143739b7e' where name='builtin.ddl-max-affect-rows' and is_builtin;
update prompt_tools set finding_key='builtin.ddl-implicit-type-conversion', definition='{"knowledge_text":"规则：WHERE条件字面值类型必须与列类型一致（旧DDLImplicitTypeConversion）。判定依据：调用schema_metadata工具核对涉及列类型，与语句字面值类型（字符串/数字）不一致时输出本发现；事实不可得不输出。","max_severity":"medium","version":1}'::jsonb, config_hash='3a5fdc1beae8df117c45a1ab97674f4c3ddcf8d41ff91ad4d56b31a145b324a7' where name='builtin.ddl-implicit-type-conversion' and is_builtin;

-- General reshape for non-builtin rows (dev data): finding_key inherits legacy template key or defaults to skill./exp.+id; max_severity takes the highest legacy whitelist severity.
update prompt_tools p set
  finding_key = coalesce(p.definition#>>'{finding_template,finding_key}', 'skill.'||p.id),
  definition = jsonb_build_object(
      'knowledge_text', p.definition->'knowledge_text',
      'max_severity', coalesce((
          select v.s from jsonb_array_elements_text(p.definition->'severity_whitelist') w(sev)
          join (values ('info',1),('low',2),('medium',3),('high',4),('critical',5)) v(s,r) on v.s = w.sev
          order by v.r desc limit 1), 'medium'),
      'version', p.definition->'version'),
  config_hash = encode(sha256(convert_to(
      '{"definition":{"knowledge_text":' || to_jsonb(p.definition->'knowledge_text')::text
      || ',"max_severity":' || to_jsonb(coalesce((
          select v.s from jsonb_array_elements_text(p.definition->'severity_whitelist') w(sev)
          join (values ('info',1),('low',2),('medium',3),('high',4),('critical',5)) v(s,r) on v.s = w.sev
          order by v.r desc limit 1), 'medium'))
      || ',"version":' || to_jsonb(p.definition->'version')::text
      || '},"engine":' || to_jsonb(p.engine)::text
      || ',"name":' || to_jsonb(p.name)::text
      || ',"parameters":' || replace(replace(p.parameters::text, ': ', ':'), ', ', ',')
      || '}', 'utf8')), 'hex')
where not p.is_builtin;
update knowledge_entries e set
  finding_key = coalesce(e.definition#>>'{finding_template,finding_key}', 'exp.'||e.id),
  definition = jsonb_build_object(
      'knowledge_text', e.definition->'knowledge_text',
      'max_severity', coalesce((
          select v.s from jsonb_array_elements_text(e.definition->'severity_whitelist') w(sev)
          join (values ('info',1),('low',2),('medium',3),('high',4),('critical',5)) v(s,r) on v.s = w.sev
          order by v.r desc limit 1), 'medium'),
      'version', e.definition->'version');

commit;
